package com.rwi.myrepublic.astri.internal;import com.rwi.myrepublic.astri.AstriConfig;import java.io.IOException;import java.net.URI;import java.net.http.HttpClient;import java.net.http.HttpRequest;import java.net.http.HttpResponse;import java.time.Duration;import java.util.Base64;public class DeviceConnectionClient{private HttpClient client;private AstriConfig config;private String authHeader;public
DeviceConnectionClient(){this.config=AstriConfig.getInstance();this.client=HttpClient.newBuilder().connectTimeout(Duration.ofMillis(config.getConnectionTimeout())).build();String credentials=config.getUsername()+ ":"+config.getPassword();this.authHeader= "Basic "+Base64.getEncoder().encodeToString(credentials.getBytes());}public String getDeviceConnections(String infrastructureType,String requestBody,int limit,int offset)throws IOException,InterruptedException{String
baseUrl=config.getApiBaseUrl();String path= "/device/connection/list/all/"+limit+ "/"+offset;String url=baseUrl+path;HttpRequest request=HttpRequest.newBuilder().uri(URI.create(url)).header("Authorization",authHeader).header("Content-Type", "application/json").timeout(Duration.ofMillis(config.getRequestTimeout())).POST(HttpRequest.BodyPublishers.ofString(requestBody)).build();HttpResponse<String>response=client.send(request,HttpResponse.BodyHandlers.ofString());return response.body();}public
String addDeviceConnection(String requestBody)throws IOException,InterruptedException{String baseUrl=config.getApiBaseUrl();String path= "/device/connection/add";String url=baseUrl+path;HttpRequest request=HttpRequest.newBuilder().uri(URI.create(url)).header("Authorization",authHeader).header("Content-Type",
"application/json").timeout(Duration.ofMillis(config.getRequestTimeout())).POST(HttpRequest.BodyPublishers.ofString(requestBody)).build();HttpResponse<String>response=client.send(request,HttpResponse.BodyHandlers.ofString());return response.body();}public void close(){}}